const hardNewsCategories = ['politics', 'world', 'u.s.', 'news'];

// Collect all direct li children
const items = Array.from(element.children).filter(el => el.tagName === 'LI');
if (items.length === 0) return;

// Classify each item
function isHardNews(li) {
  // Check data-ylk attributes on any anchor inside
  const links = li.querySelectorAll('[data-ylk]');
  for (const link of links) {
    const ylk = (link.getAttribute('data-ylk') || '').toLowerCase();
    const yga = (link.getAttribute('data-yga') || '').toLowerCase();
    // Check for content category in data-ylk (e.g. cnt_tpc:Politics)
    for (const cat of hardNewsCategories) {
      if (ylk.includes('cnt_tpc:' + cat) || yga.includes('"ycontentcategory":"' + cat)) {
        return true;
      }
    }
    // Check the visible category badge text
  }
  // Also check badge text (e.g. <div class="text-link">Politics</div>)
  const badges = li.querySelectorAll('.text-link, .label-m-emphasized');
  for (const badge of badges) {
    const text = badge.textContent.trim().toLowerCase();
    if (hardNewsCategories.includes(text)) return true;
  }
  return false;
}

const hardItems = items.filter(isHardNews);
const otherItems = items.filter(li => !isHardNews(li));

if (hardItems.length === 0) return; // nothing to reorder yet

// Re-insert: hard news first, then others — idempotent via consistent order
const allOrdered = [...hardItems, ...otherItems];
allOrdered.forEach(li => element.appendChild(li));
